export type ParsedTransferRecurringInstruction<
  TProgram extends string = typeof SUBSCRIPTIONS_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** The recurring delegation PDA to transfer from */
    delegationPda: TAccountMetas[0];
    /** The subscription-authority PDA */
    subscriptionAuthority: TAccountMetas[1];
    /** The delegator's ATA to transfer from */
    delegatorAta: TAccountMetas[2];
    /** The receiver's ATA to transfer to */
    receiverAta: TAccountMetas[3];
    /** The token mint */
    tokenMint: TAccountMetas[4];
    /** Token program */
    tokenProgram: TAccountMetas[5];
    /** The delegatee signing the transfer */
    delegatee: TAccountMetas[6];
    /** The event authority PDA */
    eventAuthority: TAccountMetas[7];
    /** This program (for self-CPI) */
    selfProgram: TAccountMetas[8];
  };
  data: TransferRecurringInstructionData;
};

export function parseTransferRecurringInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedTransferRecurringInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      delegationPda: getNextAccount(),
      subscriptionAuthority: getNextAccount(),
      delegatorAta: getNextAccount(),
      receiverAta: getNextAccount(),
      tokenMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      delegatee: getNextAccount(),
      eventAuthority: getNextAccount(),
      selfProgram: getNextAccount(),
    },
    data: getTransferRecurringInstructionDataDecoder().decode(instruction.data),
  };
}
